//! Vectors for `configure`, generated by `scripts/cpp_vectors/frame_configure_vectors.cpp` from
//! `fixtures/config-standin/policy.txt`.
//!
//! One accepted configuration (the stand-in sub-proofs, 25 empty layout links, 25 identifiers, one
//! range check), then six deterministic mutations that reach each later cross-check of
//! `configure` (no range checks, a short layout, a short identifier list, no pending row, a plain
//! scalar on a non-last link, a second message at the start), then the later reasons of
//! `key_fault` on a `KeyFixed` that the accepted configuration gives.
//!
//! Every `Configured` field printed here is compared: the refusal text, the sized summary and
//! codes, each file plan's chains and their parts/rounds/messages/verdict, the merged plans'
//! accounting, the three `Work` values, `table_columns`, `fixed` (configuration, codes, LIN shape,
//! request shape's public bytes, layout public bytes, identifiers, pending rows, binding),
//! `range_checks`, and `key_fault`. The only numbers compared with a tolerance are the doubles
//! that go through libm (the accounting's figures), printed as their bit patterns.

use fp_core::frame::configure::{configure, Configured, ProofVerdict, Shapes, ShapesOf};
use fp_core::frame::files::{stand_in_subproofs, FilePlan, Sized};
use fp_core::frame::hiding_conditions::range_check_bits;
use fp_core::frame::key_fixed::{key_fault, key_fixed, KeyFixed};
use fp_core::frame::parameters::Parameters;
use fp_core::iop::context::OracleNotice;
use fp_core::iop::relation::{Codes, OracleShape};
use fp_core::iop::req::ReqShape;
use fp_core::iop::req_rows::ReqLayout;
use fp_core::chain::public::PublicBytes;
use fp_core::frame::files::merged;
use fp_core::frame::hiding_conditions::RangeCheck;
use fp_core::hash::modes::Digest;
use fp_core::iop::foldeq::IndexShape;
use fp_core::iop::message::Writer;
use fp_core::numbers::accounting::account;
use fp_core::numbers::blocks::TableSize;
use fp_core::numbers::plan::Planned;

const POLICY: &str = include_str!("../../fixtures/config-standin/policy.txt");
const VECTORS: &str = include_str!("../../fixtures/frame_configure_vectors.txt");

// ---------------------------------------------------------------------------------------------------------------------
// The C++ tool's line format

fn hex(s: &str) -> String {
    s.as_bytes().iter().map(|b| format!("{b:02x}")).collect()
}

fn hex_or_dash(s: &str) -> String {
    if s.is_empty() {
        String::from("-")
    } else {
        hex(s)
    }
}

fn bytes_hex(v: &[u8]) -> String {
    v.iter().map(|b| format!("{b:02x}")).collect()
}

fn digest_hex(d: &Digest) -> String {
    bytes_hex(&d.to_bytes())
}

fn dbits(d: f64) -> u64 {
    d.to_bits()
}

fn shape_str(o: &OracleShape) -> String {
    format!(
        "name={} code={} main_rows={} main_deg={} mask_rows={} mask_code={} answers={}",
        hex(&o.name),
        o.code,
        o.main_rows,
        o.main_deg,
        o.mask_rows,
        o.mask_code,
        o.answers
    )
}

fn table_str(t: &TableSize) -> String {
    format!(
        "log_n={} ell={} r={} v={} answers={} radius={} later={} m_once={} m_later={}",
        t.code.log_n,
        t.code.ell,
        t.code.r,
        t.v,
        t.answers,
        t.distances.radius,
        t.distances.later_radius,
        t.distances.m_once,
        t.distances.m_later
    )
}

fn index_str(s: &IndexShape) -> String {
    format!(
        "log_n={} ell={} r={} v={} answers={} salt={} radius={} later={} m_once={} m_later={}",
        s.code.log_n,
        s.code.ell,
        s.code.r,
        s.v,
        s.answers,
        s.salt_bytes,
        s.distances.radius,
        s.distances.later_radius,
        s.distances.m_once,
        s.distances.m_later
    )
}

fn push_codes(out: &mut String, name: &str, codes: &Codes) {
    for (i, c) in codes.base.iter().enumerate() {
        out.push_str(&format!(
            "CODES name={} i={} kind=base log_n={} ell={} r={}\n",
            name, i, c.log_n, c.ell, c.r
        ));
    }
    for (i, c) in codes.mask.iter().enumerate() {
        out.push_str(&format!(
            "CODES name={} i={} kind=mask log_n={} ell={} r={}\n",
            name, i, c.log_n, c.ell, c.r
        ));
    }
}

fn ids_str(ids: &[u64]) -> String {
    if ids.is_empty() {
        return String::from("-");
    }
    ids.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")
}

fn parts_str(parts: &[String]) -> String {
    if parts.is_empty() {
        return String::from("-");
    }
    parts.iter().map(|p| hex(p)).collect::<Vec<_>>().join(",")
}

fn req_bytes(s: &ReqShape) -> String {
    let mut w = Writer::default();
    s.public_bytes(&mut w);
    bytes_hex(w.bytes())
}

fn layout_bytes(l: &ReqLayout) -> String {
    let mut w = Writer::default();
    l.public_bytes(&mut w);
    bytes_hex(w.bytes())
}

fn layout_arrays(l: &ReqLayout) -> usize {
    l.link.iter().map(|x| x.len()).sum()
}

fn push_test(out: &mut String, name: &str, test: &str, x: &fp_core::frame::derive::TestSizes) {
    out.push_str(&format!(
        "LTEST name={} test={} t={} stages={} group_name={} group_k={} group_h={}\n",
        name,
        test,
        x.t,
        x.stages.len(),
        hex(&x.group.name),
        x.group.k,
        x.group.h
    ));
}

fn push_sized(out: &mut String, name: &str, c: &Configured) {
    let z: &Sized = c.sized();
    out.push_str(&format!(
        "SIZED name={} refused={} request_bytes={}\n",
        name,
        hex_or_dash(&z.refused),
        req_bytes(&z.request)
    ));
    push_codes(out, &format!("{}/proof", name), &z.proof_codes);
    push_codes(out, &format!("{}/key", name), &z.key_codes);
    push_codes(out, &format!("{}/entry", name), &z.entry_codes);
    for once in [false, true] {
        let x = if once { &z.once } else { &z.batch };
        let s = &x.s;
        out.push_str(&format!(
            "LSIZED name={} refused={} k_lo={} matrix_rows={} columns={} batches={} shared_split={} own_split={} tests={},{},{},{} input={} input_leaf={} table={}\n",
            if once { "once" } else { "batch" },
            hex_or_dash(&x.refused),
            s.k_lo,
            s.matrix_rows,
            s.fold.columns,
            x.batches,
            u8::from(s.shared_split_needed()),
            u8::from(s.own_split_needed()),
            s.test_u.len(),
            s.test_omega.len(),
            s.test_own.len(),
            s.test_own_omega.len(),
            shape_str(&x.input.shape),
            x.input.leaf_class,
            table_str(&x.table)
        ));
        push_test(out, if once { "once" } else { "batch" }, "folded", &x.folded);
    }
    let w = &z.ranges;
    out.push_str(&format!(
        "WSIZED refused={} k_col={} rows={} message_id={} pending={} lookups={} stages={} message={} message_leaf={} ride={}\n",
        hex_or_dash(&w.refused),
        w.matrix.k_col,
        w.matrix.rows,
        w.x.message_id,
        w.pending,
        w.x.lookups.len(),
        w.x.stages.len(),
        shape_str(&w.x.message.shape),
        w.x.message.leaf_class,
        u8::from(w.x.choice.masks_ride)
    ));
    push_test(out, "ranges", "test", &w.test);
    let k = &z.link;
    out.push_str(&format!(
        "LINKSIZED refused={} columns_first={} columns_further={} code={} mask_code={} rows={} rows_high={} leaf_class={} masks_ahead={} ride={} later={} table={}\n",
        hex_or_dash(&k.refused),
        k.s.columns_first,
        k.s.columns_further,
        k.s.code,
        k.s.mask_code,
        k.s.rows,
        u8::from(k.s.rows_high),
        k.s.leaf_class,
        u8::from(k.s.masks_ahead),
        u8::from(k.s.choice.masks_ride),
        k.s.later.len(),
        index_str(&k.s.table)
    ));
    push_test(out, "link", "linked", &k.linked);
    out.push_str(&format!("TABLE {}\n", table_str(&z.d.table)));
}

fn push_file(out: &mut String, label: &str, f: &FilePlan) {
    out.push_str(&format!(
        "FILE name={} head_words={} place_depth={} has_place={} chains={}\n",
        label,
        f.head_words,
        f.place_depth,
        u8::from(f.has_place),
        f.chains.len()
    ));
    for (i, chain) in f.chains.iter().enumerate() {
        let q = &chain.plan;
        out.push_str(&format!(
            "CHAIN file={} i={} name={} parts={} parts_names={} rounds={} messages={} holds={} names={} queries={}\n",
            label,
            i,
            hex(&chain.name),
            q.parts.len(),
            parts_str(&q.parts),
            q.rounds.len(),
            q.messages.len(),
            u8::from(q.holds()),
            u8::from(q.names_of_the_format()),
            q.queries()
        ));
    }
}

fn push_account(out: &mut String, label: &str, c: &Configured, f: &FilePlan) {
    let whole: std::rc::Rc<Planned> = merged(&c.sized().d.set, std::slice::from_ref(f));
    let a = account(&whole, -1);
    out.push_str(&format!(
        "ACCOUNT file={} refused={} needs_work={} holds={} rounds={} queries={} lists_bits={} lists_work={} sum={} sum_lists={} planned_calls={}\n",
        label,
        hex_or_dash(&a.refused),
        u8::from(a.needs_work),
        u8::from(a.holds),
        a.rounds,
        a.queries,
        dbits(a.lists.bits),
        a.lists.work,
        dbits(a.sum),
        dbits(a.sum_lists),
        a.planned_calls
    ));
}

fn push_work(out: &mut String, label: &str, w: &fp_core::frame::configure::Work) {
    out.push_str(&format!(
        "WORK name={} needed={} bits_without={} bits={}\n",
        label,
        u8::from(w.needed),
        dbits(w.bits_without),
        w.bits
    ));
}

fn push_fixed(out: &mut String, c: &Configured) {
    let f = c.fixed();
    let t = c.table_columns();
    out.push_str(&format!(
        "TABLECOLUMNS bears={} one_time={} link_on_the_first={} link_on_the_further={} a_batch={} batches={}\n",
        t.bears, t.one_time, t.link_on_the_first, t.link_on_the_further, t.a_batch, t.batches
    ));
    out.push_str(&format!(
        "FIXED configuration={} pending_rows={} ids_n={} ids={} binding_log_leaves={} binding_salt_bytes={}\n",
        digest_hex(&f.configuration),
        f.pending_rows,
        f.identifiers.len(),
        ids_str(&f.identifiers),
        f.binding.log_leaves,
        f.binding.salt_bytes
    ));
    push_codes(out, "fixed", &f.codes);
    let s = &f.lin;
    out.push_str(&format!(
        "FIXLIN k_lo={} matrix_rows={} columns={} masks_ahead={} ride={} shared_split={} own_split={} omega_lc={} split_lc={} w_lc={} own_lc={} tests={},{},{},{}\n",
        s.k_lo,
        s.matrix_rows,
        s.fold.columns,
        u8::from(s.masks_ahead),
        u8::from(s.choice.masks_ride),
        u8::from(s.shared_split_needed()),
        u8::from(s.own_split_needed()),
        s.omega_leaf_class,
        s.shared_split_leaf_class,
        s.w_leaf_class,
        s.own_split_leaf_class,
        s.test_u.len(),
        s.test_omega.len(),
        s.test_own.len(),
        s.test_own_omega.len()
    ));
    out.push_str(&format!("FIXREQ bytes={}\n", req_bytes(&f.shape)));
    out.push_str(&format!(
        "LAYOUT links={} arrays={} bytes={}\n",
        f.layout.link.len(),
        layout_arrays(&f.layout),
        layout_bytes(&f.layout)
    ));
    out.push_str(&format!("RANGECHECKS n={}\n", c.range_checks().len()));
    for (i, r) in c.range_checks().iter().enumerate() {
        out.push_str(&format!(
            "RANGECHECK i={} rows={} columns={} combinations={} bound={} range={} digit_bits={},{} bits={}\n",
            i,
            r.rows,
            r.columns,
            r.combinations,
            r.bound,
            r.range,
            r.digit_bits[0],
            r.digit_bits[1],
            range_check_bits(r)
        ));
    }
    let fault = key_fault(&key_fixed(c.sized(), c.configuration()));
    out.push_str(&format!(
        "KEYFAULT {}\n",
        match fault {
            Some(w) => hex(w),
            None => String::from("-"),
        }
    ));
}

fn push_case(out: &mut String, name: &str, c: &Configured) {
    out.push_str(&format!("CASE name={}\n", name));
    out.push_str(&format!("REFUSED {}\n", hex_or_dash(c.refused())));
    push_sized(out, name, c);
    push_file(out, "proof", c.proof());
    push_file(out, "key", c.key());
    push_file(out, "entry", c.entry());
    push_account(out, "proof", c, c.proof());
    push_account(out, "key", c, c.key());
    push_account(out, "entry", c, c.entry());
    push_work(
        out,
        "proof",
        &fp_core::frame::configure::Work {
            needed: c.needs_work(),
            bits_without: c.bits_without_work(),
            bits: c.work(),
        },
    );
    push_work(out, "key", c.work_of_the_key());
    push_work(out, "entry", c.work_of_an_entry());
    push_fixed(out, c);
}

// ---------------------------------------------------------------------------------------------------------------------
// The cases

fn good_check() -> RangeCheck {
    RangeCheck {
        rows: 1,
        columns: 1,
        combinations: 1,
        bound: 2,
        range: 1 << 19,
        digit_bits: [10, 10],
    }
}

const BASE: usize = 0;

fn shapes_for(variant: usize) -> Shapes {
    let mut s = Shapes {
        sub: stand_in_subproofs(),
        ..Shapes::default()
    };
    s.layout.link = vec![Vec::new(); s.sub.request.link.len()];
    s.identifiers = (0..s.sub.request.link.len() as u64).map(|i| 1000 + i).collect();
    s.range_checks.push(good_check());
    match variant {
        1 => s.range_checks.clear(),
        2 => {
            let n = s.sub.request.link.len() - 1;
            s.layout.link.resize(n, Vec::new());
        }
        3 => {
            s.identifiers.pop();
        }
        4 => s.sub.pending_rows = 0,
        5 => s.sub.request.link[0].plain = 1,
        6 => s.sub.request.at_start.push(OracleNotice {
            shape: OracleShape {
                name: String::from("extra at the start"),
                code: 0,
                main_rows: 0,
                main_deg: 1,
                mask_rows: 1,
                mask_code: 0,
                answers: 1,
            },
            leaf_class: 100,
        }),
        _ => {}
    }
    s
}

fn run_case(out: &mut String, name: &str, variant: usize) {
    let files: [&[u8]; 1] = [POLICY.as_bytes()];
    let shapes: &ShapesOf<'_> = &|_: &[&[u8]], _: &Parameters| shapes_for(variant);
    let c = configure(&files, shapes);
    push_case(out, name, &c);
}

fn push_key_fault_case(out: &mut String, name: &str, what: &str, f: &KeyFixed) {
    let why = key_fault(f);
    out.push_str(&format!(
        "KEYFAULT2 name={} case={} fault={}\n",
        name,
        what,
        match why {
            Some(w) => hex(w),
            None => String::from("-"),
        }
    ));
}

fn push_key_fault_cases(out: &mut String, name: &str, base: &KeyFixed) {
    push_key_fault_case(out, name, "base", base);
    {
        let mut f = base.clone();
        f.lin.matrix_rows = 0;
        push_key_fault_case(out, name, "lin", &f);
    }
    {
        let mut f = base.clone();
        f.ranges.lookups.clear();
        push_key_fault_case(out, name, "ranges", &f);
    }
    {
        let mut f = base.clone();
        f.binding.log_leaves = 1;
        push_key_fault_case(out, name, "binding", &f);
    }
    {
        let mut f = base.clone();
        f.ranges.message_id = 0;
        push_key_fault_case(out, name, "message_id", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.main_rows = 1;
        push_key_fault_case(out, name, "mask_main_rows", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.mask_rows = 0;
        push_key_fault_case(out, name, "mask_no_rows", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.answers = 0;
        push_key_fault_case(out, name, "mask_no_answers", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.mask_code = f.codes.mask.len() as u32;
        push_key_fault_case(out, name, "mask_code", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.mask_rows = 1;
        let code = f.index_masks.shape.mask_code as usize;
        let ell = if f.codes.mask.is_empty() {
            1
        } else {
            f.codes.mask[if code < f.codes.mask.len() { code } else { 0 }].ell as u32
        };
        f.index_masks.shape.answers = ell;
        push_key_fault_case(out, name, "mask_no_room", &f);
    }
}

#[test]
fn frame_configure_matches_the_cpp_reference() {
    let mut out = String::new();
    for (v, name) in [
        "base",
        "no_checks",
        "layout_short",
        "identifiers_short",
        "pending_zero",
        "plain_first",
        "extra_at_start",
    ]
    .iter()
    .enumerate()
    {
        run_case(&mut out, name, v);
    }
    // The same accepted configuration's key, with one field broken at a time.
    let files: [&[u8]; 1] = [POLICY.as_bytes()];
    let base_shapes: &ShapesOf<'_> = &|_: &[&[u8]], _: &Parameters| shapes_for(BASE);
    let c = configure(&files, base_shapes);
    let key = key_fixed(c.sized(), c.configuration());
    push_key_fault_cases(&mut out, "base", &key);

    let got: Vec<&str> = out.lines().collect();
    let want: Vec<&str> = VECTORS.lines().collect();
    for i in 0..got.len().min(want.len()) {
        if !same_line(got[i], want[i]) {
            let a = got[i];
            let b = want[i];
            panic!(
                "line {} differs\n  rust: {}\n  cpp:  {}",
                i + 1,
                if a.len() > 400 { &a[..400] } else { a },
                if b.len() > 400 { &b[..400] } else { b }
            );
        }
    }
    assert_eq!(got.len(), want.len(), "the number of lines");
}

/// The accounting's figures go through libm: the C++ and Rust libraries may differ in the last
/// bits, as in the plan-emitter and frame-file vectors. Everything else is exact.
fn same_line(got: &str, want: &str) -> bool {
    if got == want {
        return true;
    }
    let g: Vec<&str> = got.split(' ').collect();
    let w: Vec<&str> = want.split(' ').collect();
    if g.len() != w.len() {
        return false;
    }
    let double_fields: &[usize] = match g.first() {
        Some(&"ACCOUNT") => &[7, 9, 10],
        Some(&"WORK") => &[3],
        _ => return false,
    };
    for i in 0..g.len() {
        if double_fields.contains(&i) {
            if !close_float(g[i], w[i]) {
                return false;
            }
        } else if g[i] != w[i] {
            return false;
        }
    }
    true
}

fn close_float(a: &str, b: &str) -> bool {
    // The tokens carry their field's name: `lists_bits=<bit pattern>`.
    let a = a.rsplit_once('=').map_or(a, |(_, v)| v);
    let b = b.rsplit_once('=').map_or(b, |(_, v)| v);
    let x = f64::from_bits(a.parse::<u64>().unwrap());
    let y = f64::from_bits(b.parse::<u64>().unwrap());
    let tol = 1e-9 * x.abs().max(y.abs()).max(1.0);
    (x - y).abs() <= tol
}

#[test]
fn the_verdict_enum_has_no_implicit_bool() {
    let _: ProofVerdict = ProofVerdict::YesWithWork;
    assert_ne!(ProofVerdict::default(), ProofVerdict::Yes);
}
